<?php
declare(strict_types=1);
require dirname(__DIR__) . '/config.php';

$page = $_GET['page'] ?? 'home';
$user = current_user();

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    check_csrf();
    $action = $_POST['action'] ?? '';
    try {
        if ($action === 'register') {
            $username = trim($_POST['username'] ?? ''); $email = trim($_POST['email'] ?? ''); $password = $_POST['password'] ?? '';
            if (!preg_match('/^[a-zA-Z0-9_]{3,40}$/', $username) || !filter_var($email, FILTER_VALIDATE_EMAIL) || strlen($password) < 8) throw new RuntimeException('Usa un nombre válido, email válido y contraseña de 8+ caracteres.');
            $q = $pdo->prepare('INSERT INTO users(username,email,password_hash) VALUES(?,?,?)'); $q->execute([$username,$email,password_hash($password,PASSWORD_DEFAULT)]); flash('Cuenta creada. Ya puedes iniciar sesión.'); redirect(url('login'));
        }
        if ($action === 'login') {
            $q = $pdo->prepare('SELECT * FROM users WHERE email=? OR username=? LIMIT 1'); $q->execute([trim($_POST['identity'] ?? ''), trim($_POST['identity'] ?? '')]); $found = $q->fetch();
            if (!$found || !password_verify($_POST['password'] ?? '', $found['password_hash'])) throw new RuntimeException('Credenciales incorrectas.');
            if ($found['is_banned']) throw new RuntimeException('Tu cuenta está suspendida por moderación.');
            session_regenerate_id(true); unset($found['password_hash']); $_SESSION['user'] = $found; flash('Sesión iniciada.'); redirect(url('home'));
        }
        if ($action === 'logout') { $_SESSION = []; session_destroy(); redirect(url('home')); }
        if ($action === 'create_post') {
            if (!$user) throw new RuntimeException('Inicia sesión para publicar.');
            $title = trim($_POST['title'] ?? ''); $body = trim($_POST['body'] ?? ''); $category = (int)($_POST['category_id'] ?? 0); $security = !empty($_POST['is_security']) ? 1 : 0;
            if (strlen($title) < 5 || strlen($body) < 20 || !$category) throw new RuntimeException('Completa título, contenido y categoría.');
            $image = null;
            if (!empty($_FILES['image']['tmp_name'])) { if ($_FILES['image']['size'] > 5*1024*1024 || !in_array((new finfo(FILEINFO_MIME_TYPE))->file($_FILES['image']['tmp_name']), ['image/jpeg','image/png','image/webp'], true)) throw new RuntimeException('La imagen debe ser JPG, PNG o WebP de máximo 5 MB.'); $ext = strtolower(pathinfo($_FILES['image']['name'], PATHINFO_EXTENSION)); $image = 'uploads/' . bin2hex(random_bytes(12)) . '.' . $ext; move_uploaded_file($_FILES['image']['tmp_name'], __DIR__ . '/' . $image); }
            $q = $pdo->prepare('INSERT INTO posts(category_id,user_id,title,body,image_path,is_security) VALUES(?,?,?,?,?,?)'); $q->execute([$category,$user['id'],$title,$body,$image,$security]); flash('Post publicado.'); redirect(url('thread',['id'=>$pdo->lastInsertId()]));
        }
        if ($action === 'comment') { if (!$user) throw new RuntimeException('Inicia sesión para comentar.'); $body=trim($_POST['body']??''); $post=(int)$_POST['post_id']; if (strlen($body)<2) throw new RuntimeException('El comentario está vacío.'); $q=$pdo->prepare('INSERT INTO comments(post_id,user_id,body) VALUES(?,?,?)'); $q->execute([$post,$user['id'],$body]); redirect(url('thread',['id'=>$post])); }
        if ($action === 'moderate' && is_staff()) {
            $target = $_POST['target'] ?? ''; $id=(int)($_POST['id']??0);
            if ($target==='close_post') $pdo->prepare('UPDATE posts SET is_closed=1 WHERE id=?')->execute([$id]);
            if ($target==='ban_user') $pdo->prepare('UPDATE users SET is_banned=1 WHERE id=?')->execute([$id]);
            if ($target==='unban_user') $pdo->prepare('UPDATE users SET is_banned=0 WHERE id=?')->execute([$id]);
            if ($target==='chat_toggle') $pdo->prepare("UPDATE settings SET setting_value=IF(setting_value='1','0','1') WHERE setting_key='chat_enabled'")->execute();
            if ($target==='badge' && is_admin()) { $badge=(int)$_POST['badge_id']; $pdo->prepare('INSERT IGNORE INTO user_badges(user_id,badge_id) VALUES(?,?)')->execute([$id,$badge]); }
            flash('Moderación aplicada.'); redirect(url('admin'));
        }
        if ($action === 'category' && is_admin()) { $name=trim($_POST['name']??''); $slug=preg_replace('/[^a-z0-9-]+/','-',strtolower(trim($_POST['slug']??$name))); $parent=(int)($_POST['parent_id']??0) ?: null; if (!$name) throw new RuntimeException('El nombre es obligatorio.'); $pdo->prepare('INSERT INTO categories(parent_id,name,slug,description) VALUES(?,?,?,?)')->execute([$parent,$name,$slug,trim($_POST['description']??'')]); flash('Categoría creada.'); redirect(url('admin')); }
    } catch (Throwable $ex) { flash($ex->getMessage(), 'error'); redirect($_SERVER['HTTP_REFERER'] ?? url('home')); }
}

$flash = flash();
function header_html(string $title): void { global $user,$pdo; $chat=setting($pdo,'chat_enabled','1'); ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · RustForge</title><link rel="stylesheet" href="assets/style.css"></head><body>
<header class="topbar"><a class="brand" href="<?=url()?>"><span class="brand-mark">R/</span><span>RUSTFORGE<small>COMMUNITY CLIENT</small></span></a><nav><a href="<?=url()?>">Inicio</a><a href="<?=url('security')?>">Seguridad</a><?php if($user):?><a href="<?=url('new')?>">Nuevo post</a><?php endif;?><?php if(is_staff()):?><a href="<?=url('admin')?>">Moderar</a><?php endif;?></nav><div class="account"><?php if($user):?><span class="user-chip">@<?=e($user['username'])?> <b><?=e($user['role'])?></b></span><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><button class="link-btn" name="action" value="logout">Salir</button></form><?php else:?><a class="button small" href="<?=url('login')?>">Entrar</a><?php endif;?></div></header>
<main class="shell"><?php if($flash):?><div class="flash <?=$flash[1]?>"><?=e($flash[0])?></div><?php endif; ?>
<?php }
function footer_html(): void { global $pdo; $chat=setting($pdo,'chat_enabled','1'); ?></main><footer><span>RUSTFORGE / COMMUNITY CLIENT</span><span>Construido para compartir builds, fallos y soluciones.</span></footer></body></html><?php }

if ($page==='login' || $page==='register') { header_html($page==='login'?'Iniciar sesión':'Crear cuenta'); ?><section class="auth-card"><span class="eyebrow">ACCESS / <?= $page==='login'?'01':'02' ?></span><h1><?= $page==='login'?'Vuelve al taller.':'Únete al taller.' ?></h1><p class="muted"><?= $page==='login'?'Accede a tus posts, insignias y conversaciones.':'Crea tu identidad en la comunidad del cliente.' ?></p><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="<?=$page?>"><?php if($page==='register'):?><label>Usuario<input name="username" required maxlength="40" placeholder="rustbuilder"></label><label>Email<input type="email" name="email" required placeholder="you@example.com"></label><?php else:?><label>Usuario o email<input name="identity" required></label><?php endif;?><label>Contraseña<input type="password" name="password" required minlength="8"></label><button class="button">Continuar <span>→</span></button></form><p class="switch"><?php if($page==='login'):?>¿Nuevo aquí? <a href="<?=url('register')?>">Crear cuenta</a><?php else:?>¿Ya tienes cuenta? <a href="<?=url('login')?>">Entrar</a><?php endif;?></p></section><?php footer_html(); exit; }

if ($page==='new') { header_html('Nuevo post'); $cats=$pdo->query('SELECT c.*, p.name parent_name FROM categories c LEFT JOIN categories p ON p.id=c.parent_id ORDER BY COALESCE(p.name,c.name),c.name')->fetchAll(); ?><section class="page-head"><span class="eyebrow">PUBLISH / FIELD NOTE</span><h1>Abre una conversación.</h1><p class="muted">Documenta un cambio, una idea o un fallo reproducible. Los reportes de seguridad se señalizan para la moderación.</p></section><form method="post" enctype="multipart/form-data" class="form-card"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create_post"><label>Título<input name="title" maxlength="180" required placeholder="v1.4.0 — nuevo sistema de inventario"></label><label>Categoría<select name="category_id" required><option value="">Selecciona...</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['parent_name'] ? $c['parent_name'].' / ' : '')?><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Contenido<textarea name="body" rows="10" required placeholder="Qué cambió, cómo reproducirlo o qué feedback necesitas..."></textarea></label><label class="check"><input type="checkbox" name="is_security"> Marcar como reporte de seguridad</label><label>Captura o evidencia <input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG o WebP · máximo 5 MB</small></label><button class="button">Publicar post <span>→</span></button></form><?php footer_html(); exit; }

if ($page==='thread') { $id=(int)($_GET['id']??0); $q=$pdo->prepare('SELECT p.*, c.name category_name, u.username, u.role FROM posts p JOIN categories c ON c.id=p.category_id JOIN users u ON u.id=p.user_id WHERE p.id=?'); $q->execute([$id]); $post=$q->fetch(); if(!$post){http_response_code(404);header_html('No encontrado');echo'<div class="empty"><h2>Post no encontrado.</h2></div>';footer_html();exit;} $comments=$pdo->prepare('SELECT cm.*,u.username,u.role FROM comments cm JOIN users u ON u.id=cm.user_id WHERE post_id=? ORDER BY cm.created_at');$comments->execute([$id]); header_html($post['title']); ?><article class="thread"><div class="thread-meta"><a href="<?=url('category',['id'=>$post['category_id']])?>">← <?=e($post['category_name'])?></a><span><?=date('d M Y · H:i',strtotime($post['created_at']))?></span></div><div class="thread-title"><div><?php if($post['is_security']):?><span class="pill security">SECURITY</span><?php endif;?><?php if($post['is_closed']):?><span class="pill closed">CLOSED</span><?php endif;?></div><h1><?=e($post['title'])?></h1><p class="byline">por <strong>@<?=e($post['username'])?></strong> · <?=e($post['role'])?></p></div><div class="thread-body"><?=nl2br(e($post['body']))?><?php if($post['image_path']):?><img class="evidence" src="<?=e($post['image_path'])?>" alt="Evidencia adjunta"><?php endif;?></div></article><section class="comments"><div class="section-label">DISCUSSION / <?= $comments->rowCount() ?></div><?php foreach($comments as $cm):?><div class="comment"><div class="avatar"><?=strtoupper(substr($cm['username'],0,1))?></div><div><strong>@<?=e($cm['username'])?></strong><span class="muted"> · <?=date('d M H:i',strtotime($cm['created_at']))?></span><p><?=nl2br(e($cm['body']))?></p></div></div><?php endforeach;?><?php if($user && !$post['is_closed']):?><form method="post" class="comment-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="comment"><input type="hidden" name="post_id" value="<?=$id?>"><textarea name="body" rows="3" placeholder="Aporta una respuesta..."></textarea><button class="button small">Responder</button></form><?php elseif($post['is_closed']):?><p class="muted">Este post está cerrado para nuevas respuestas.</p><?php endif;?></section><?php footer_html(); exit; }

if ($page==='category') { $id=(int)($_GET['id']??0); $q=$pdo->prepare('SELECT * FROM categories WHERE id=?');$q->execute([$id]);$cat=$q->fetch();$q=$pdo->prepare('SELECT p.*,u.username FROM posts p JOIN users u ON u.id=p.user_id WHERE p.category_id=? ORDER BY p.created_at DESC');$q->execute([$id]); header_html($cat['name']??'Categoría'); ?><section class="page-head compact"><span class="eyebrow">CHANNEL / <?=str_pad((string)$id,2,'0',STR_PAD_LEFT)?></span><h1><?=e($cat['name']??'Categoría')?></h1><p class="muted"><?=e($cat['description']??'')?></p></section><section class="post-list"><?php foreach($q as $p):?><a class="post-row" href="<?=url('thread',['id'=>$p['id']])?>"><div><div><?php if($p['is_security']):?><span class="pill security">SECURITY</span><?php endif;?><?php if($p['is_closed']):?><span class="pill closed">CLOSED</span><?php endif;?></div><h3><?=e($p['title'])?></h3><span class="muted">@<?=e($p['username'])?> · <?=date('d M Y',strtotime($p['created_at']))?></span></div><span class="arrow">↗</span></a><?php endforeach; if(!$q->rowCount()):?><div class="empty">Aún no hay posts en este canal.</div><?php endif;?></section><?php footer_html(); exit; }

if ($page==='security') { $q=$pdo->query("SELECT p.*,u.username,c.name category_name FROM posts p JOIN users u ON u.id=p.user_id JOIN categories c ON c.id=p.category_id WHERE p.is_security=1 ORDER BY p.created_at DESC"); header_html('Reportes de seguridad'); ?><section class="page-head"><span class="eyebrow">SECURITY / WATCHLIST</span><h1>Ojos sobre los fallos.</h1><p class="muted">Reportes compartidos por la comunidad. No publiques credenciales, exploits activos ni datos personales.</p></section><section class="post-list"><?php foreach($q as $p):?><a class="post-row security-row" href="<?=url('thread',['id'=>$p['id']])?>"><div><span class="pill security">SECURITY</span><h3><?=e($p['title'])?></h3><span class="muted">@<?=e($p['username'])?> · <?=date('d M Y',strtotime($p['created_at']))?></span></div><span class="arrow">↗</span></a><?php endforeach;?></section><?php footer_html(); exit; }

if ($page==='admin' && is_staff()) { $posts=$pdo->query('SELECT p.id,p.title,p.is_closed,p.created_at,u.id user_id,u.username,u.is_banned FROM posts p JOIN users u ON u.id=p.user_id ORDER BY p.created_at DESC LIMIT 30')->fetchAll();$users=$pdo->query('SELECT id,username,role,is_banned FROM users ORDER BY created_at DESC LIMIT 30')->fetchAll();$cats=$pdo->query('SELECT c.*,p.name parent_name FROM categories c LEFT JOIN categories p ON p.id=c.parent_id ORDER BY c.name')->fetchAll();$badges=$pdo->query('SELECT * FROM badges')->fetchAll(); header_html('Panel de moderación'); ?><section class="page-head compact"><span class="eyebrow">CONTROL ROOM / STAFF</span><h1>Moderación y estructura.</h1><p class="muted">Acciones de moderación simples, visibles y reversibles cuando corresponde.</p></section><div class="admin-grid"><section class="panel"><div class="section-label">POSTS RECIENTES</div><?php foreach($posts as $p):?><div class="admin-row"><div><a href="<?=url('thread',['id'=>$p['id']])?>"><?=e($p['title'])?></a><small>@<?=e($p['username'])?></small></div><?php if(!$p['is_closed']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="moderate"><input type="hidden" name="target" value="close_post"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="button danger small">Cerrar</button></form><?php else:?><span class="pill closed">CLOSED</span><?php endif;?></div><?php endforeach;?></section><section class="panel"><div class="section-label">USUARIOS</div><?php foreach($users as $u):?><div class="admin-row"><div><strong>@<?=e($u['username'])?></strong><small><?=e($u['role'])?></small></div><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="moderate"><input type="hidden" name="target" value="<?=$u['is_banned']?'unban_user':'ban_user'?>"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="button <?= $u['is_banned']?'':'danger'?> small"><?=$u['is_banned']?'Desbanear':'Banear'?></button></form></div><?php endforeach;?></section><section class="panel"><div class="section-label">CATEGORÍAS</div><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="category"><input name="name" placeholder="Nombre de categoría" required><input name="slug" placeholder="slug-opcional"><select name="parent_id"><option value="0">Sin categoría padre</option><?php foreach($cats as $c): if(!$c['parent_id']):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endif; endforeach;?></select><input name="description" placeholder="Descripción"><button class="button small">Crear categoría</button></form><hr><?php foreach($cats as $c):?><div class="tree-item"><?=e($c['parent_name']?'↳ ':'')?><?=e($c['name'])?></div><?php endforeach;?></section><section class="panel"><div class="section-label">COMUNIDAD</div><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="moderate"><input type="hidden" name="target" value="chat_toggle"><button class="button"><?=setting($pdo,'chat_enabled','1')==='1'?'Desactivar chat':'Activar chat'?></button></form><p class="muted">Chat global: <strong><?=setting($pdo,'chat_enabled','1')==='1'?'activo':'desactivado'?></strong></p><?php if(is_admin()):?><hr><div class="section-label">INSIGNIAS</div><?php foreach($badges as $b):?><div class="admin-row"><span><?=e($b['icon'])?> <?=e($b['name'])?></span><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="moderate"><input type="hidden" name="target" value="badge"><select name="id" aria-label="Usuario para insignia"><?php foreach($users as $badge_user):?><option value="<?=$badge_user['id']?>">@<?=e($badge_user['username'])?></option><?php endforeach;?></select><input type="hidden" name="badge_id" value="<?=$b['id']?>"><button class="button small">Asignar</button></form></div><?php endforeach;?><?php endif;?></section></div><?php footer_html(); exit; }

// HOME
header_html('Inicio'); $cats=$pdo->query('SELECT c.*, COUNT(p.id) post_count FROM categories c LEFT JOIN posts p ON p.category_id=c.id GROUP BY c.id ORDER BY c.parent_id IS NOT NULL,c.name')->fetchAll();$posts=$pdo->query('SELECT p.*,u.username,c.name category_name FROM posts p JOIN users u ON u.id=p.user_id JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC LIMIT 6')->fetchAll(); ?><section class="hero"><div><span class="eyebrow">RUSTFORGE / COMMUNITY CLIENT</span><h1>El taller donde<br><em>los cambios cobran vida.</em></h1><p>Changelogs, reportes de seguridad y conversaciones para construir un cliente Rust mejor con tu comunidad.</p><div class="hero-actions"><a class="button" href="<?=url('new')?>">Publicar cambio <span>→</span></a><a class="text-link" href="<?=url('security')?>">Ver seguridad ↗</a></div></div><div class="hero-stamp"><span>BUILD</span><strong>0.4<span>.8</span></strong><small>COMMUNITY PREVIEW</small></div></section><div class="home-grid"><section><div class="section-heading"><span class="section-label">LATEST SIGNALS</span><a href="<?=url('new')?>">+ nuevo post</a></div><?php foreach($posts as $p):?><a class="post-row" href="<?=url('thread',['id'=>$p['id']])?>"><div><?php if($p['is_security']):?><span class="pill security">SECURITY</span><?php endif;?><h3><?=e($p['title'])?></h3><span class="muted"><?=e($p['category_name'])?> · @<?=e($p['username'])?> · <?=date('d M',strtotime($p['created_at']))?></span></div><span class="arrow">↗</span></a><?php endforeach;?></section><aside><div class="section-label">CHANNELS / <?=count($cats)?></div><?php foreach($cats as $c):?><a class="channel" href="<?=url('category',['id'=>$c['id']])?>"><span class="channel-index">#<?=str_pad((string)$c['id'],2,'0',STR_PAD_LEFT)?></span><span><strong><?=e($c['name'])?></strong><small><?=e($c['description'])?></small></span><b><?=$c['post_count']?></b></a><?php endforeach;?><div class="callout"><span class="eyebrow">SAFETY FIRST</span><p>¿Encontraste un fallo? Compártelo con contexto y sin exponer secretos.</p><a href="<?=url('security')?>">Abrir watchlist →</a></div></aside></div><?php footer_html(); ?>